/// `GET /api/v1/status` — the snapshot, filtered to what this device may read.
public struct RelaySnapshot: Sendable {
    public let instanceId: String
    public let schemaVersion: Int
    public let generatedAt: Date
    public let ageSeconds: Int
    /// True when the relay has not had a fresh push within its configured
    /// window. The data is still returned; the UI must label it, never hide it.
    public let stale: Bool
    public let roles: [String]
    /// Section name to raw JSON. Decoded lazily by the feature that needs it,
    /// so an unknown or changed section never breaks the whole screen.
    public let sections: [String: Data]

    /// Decodes one section into a concrete type.
    public func decode<T: Decodable>(_ type: T.Type, section: String, using decoder: JSONDecoder = RelayJSON.decoder) throws -> T? {
        guard let data = sections[section] else { return nil }
        return try decoder.decode(T.self, from: data)
    }

    /// One section as generic JSON, for a section this build has no type for.
    ///
    /// This is what lets the relay grow a section without an app release: the
    /// UI renders whatever arrives as labelled rows instead of hiding it.
    public func value(section: String) -> RelayJSONValue? {
        guard let data = sections[section] else { return nil }
        return try? RelayJSON.decoder.decode(RelayJSONValue.self, from: data)
    }
}

extension RelaySnapshot: Decodable {
    private enum CodingKeys: String, CodingKey {
        case instanceId, schemaVersion, generatedAt, ageSeconds, stale, roles, sections
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        instanceId = try container.decode(String.self, forKey: .instanceId)
        schemaVersion = try container.decode(Int.self, forKey: .schemaVersion)
        generatedAt = try container.decode(Date.self, forKey: .generatedAt)
        ageSeconds = try container.decode(Int.self, forKey: .ageSeconds)
        stale = try container.decode(Bool.self, forKey: .stale)
        roles = try container.decodeIfPresent([String].self, forKey: .roles) ?? []

        // Sections stay as raw JSON. The relay deliberately treats them as
        // opaque, and so does the app: a new field, or a whole new section,
        // must never fail the decode of the screen the user is looking at.
        let raw = try container.decodeIfPresent([String: RelayRawJSON].self, forKey: .sections) ?? [:]
        sections = raw.mapValues(\.data)
    }
}

/// A JSON value captured as its encoded bytes.
struct RelayRawJSON: Decodable {
    let data: Data

    init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        let value = try container.decode(RelayJSONValue.self)
        data = try RelayJSON.rawEncoder.encode(value)
    }
}

/// A minimal `any JSON` representation.
///
/// Used to round-trip an opaque section back into `Data`, and to render a
/// section this build has no concrete type for.
public indirect enum RelayJSONValue: Codable, Sendable, Equatable {
    case null
    case bool(Bool)
    /// Integers are kept distinct from `number` on purpose. Everything the
    /// relay carries in this position is a count — assets, vulnerabilities,
    /// servers processed — and routing those through `Double` renders 1234 as
    /// "1234.0" and loses precision past 2^53.

item.aggregated_output:
         *                         .getPendingCount           @Secured("ADMIN","SECCHAMPION")
         *  - [SECTION_IMPORTS]    CrowdStrikeController      ADMIN/VULN
         *  - the remaining three are the admin summary, which is ADMIN-only.
         *
         * **When you change a controller's `@Secured`, change the matching row
         * here.** Nothing in the build can catch the drift: the relay will
         * happily enforce whatever it is told, and the result is a phone
         * showing data the web UI would refuse. `RelaySnapshotBuilderTest`
         * pins the pairs that exist today.
         */
        val SECTION_POLICIES: Map<String, RelaySectionPolicy> = mapOf(
            SECTION_TOTALS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Asset, vulnerability and user counts"
            ),
            SECTION_KPIS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN", "SECCHAMPION"),
                description = "AWS clean-server and EDR coverage KPIs"
            ),
            SECTION_EXCEPTIONS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN", "SECCHAMPION"),
                description = "Vulnerability exception requests awaiting review"
            ),
            SECTION_IMPORTS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN", "VULN"),
                description = "Freshness of the last CrowdStrike import"
            ),
            SECTION_TOP_PRODUCTS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Products with the most vulnerabilities"
            ),
            SECTION_TOP_SERVERS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Servers with the most vulnerabilities"
            ),
            SECTION_INTEGRATIONS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Integration finding counts and scan coverage freshness"
            )
        )

        /** Renders an instant as the RFC 3339 UTC string the relay parses. */
        fun rfc3339(instant: Instant): String = DateTimeFormatter.ISO_INSTANT.format(instant)

        /**
         * Renders a zone-less [LocalDateTime] as an ISO local timestamp.
     * the whole push: a broken KPI cache should degrade one tile in the app,
     * not blind the on-call admin to everything else.
     */
    open fun build(instanceId: String, sections: List<String>): RelaySnapshot {
        val requested = sections.ifEmpty { ALL_SECTIONS }
        val built = LinkedHashMap<String, Any>()

        for (section in requested) {
            val value = try {
                buildSection(section)
            } catch (e: Exception) {
                logger.warn("Relay snapshot section '{}' could not be built and was omitted: {}", section, e.message)
                null
            }
            if (value != null) {
                built[section] = value
            }
        }

        if (built.isEmpty()) {
            // The relay refuses an empty snapshot, so say why here rather than
            // letting it come back as an opaque 400.
            throw IllegalStateException("No relay snapshot section could be built; check secman.relay.sections")
        }

        // Every section must carry a policy or the relay refuses the whole
        // push. That is the desired failure: a section nobody can read looks
        // exactly like a broken app, and this way it surfaces here instead.
        val policy = built.keys.associateWith { name ->
            SECTION_POLICIES[name]
                ?: throw IllegalStateException("Relay section '$name' has no role policy in SECTION_POLICIES")
        }

        return RelaySnapshot(
            instanceId = instanceId,
            generatedAt = rfc3339(Instant.now()),
            sections = built,
            policy = policy
        )
    }

    private fun buildSection(section: String): Any? = when (section) {
        SECTION_TOTALS -> buildTotals()
        SECTION_KPIS -> buildKpis()
        SECTION_EXCEPTIONS -> buildExceptions()
        SECTION_IMPORTS -> buildImports()
        SECTION_TOP_PRODUCTS -> buildTopProducts()
        SECTION_TOP_SERVERS -> buildTopServers()
        SECTION_INTEGRATIONS -> buildIntegrations()
        else -> {
            logger.warn("Unknown relay snapshot section '{}' requested; ignoring", section)
            null
        }
    }

    private fun buildIntegrations(): Map<String, Any> {
        val summary = integrationReadService.globalSummary()
        return mapOf("scanners" to summary.scanners, "totalSubjects" to summary.totalSubjects,
            "healthySubjects" to summary.healthySubjects, "failedSubjects" to summary.failedSubjects,
            "unscannedSubjects" to summary.unscannedSubjects, "staleSubjects" to summary.staleSubjects,
            "openFindings" to summary.openFindings)
    }

    private fun buildTotals(): Map<String, Any> {
        val stats = adminSummaryService.getSystemStatistics()
        return mapOf(
            "assets" to stats.assetCount,
            "vulnerabilities" to stats.vulnerabilityCount,
            "users" to stats.userCount
        )
    }

    private fun buildKpis(): Map<String, Any> {
        val aws = awsCleanServerKpiService.getKpi()
        val edr = edrCoverageKpiService.getKpi()

        // `available = false` is passed through rather than smoothed to zero:
        // "not measured yet" and "0% coverage" mean opposite things to whoever
        // is looking at the phone.
        val awsKpi = LinkedHashMap<String, Any>()
        awsKpi["available"] = aws.available
        aws.percentage?.let { awsKpi["percentage"] = it }
        aws.totalAwsServers?.let { awsKpi["totalServers"] = it }
        aws.cleanAwsServers?.let { awsKpi["cleanServers"] = it }
        isoLocal(aws.lastCalculatedAt)?.let { awsKpi["lastCalculatedAt"] = it }

        val edrKpi = LinkedHashMap<String, Any>()
        edrKpi["available"] = edr.available
        edr.percentage?.let { edrKpi["percentage"] = it }
        edr.totalEc2Instances?.let { edrKpi["totalInstances"] = it }
        edr.eligibleEc2Instances?.let { edrKpi["eligibleInstances"] = it }
// Package api implements the device -> relay plane: the read-only API a mobile
// client talks to.
//
// Four properties hold across every route here.
//
//   - **Read-only.** No route mutates secman state, because no path from the
//     relay back to secman exists at all.
//   - **Authenticated per request.** Nothing is served on the basis of being on
//     the network, holding a long-lived shared secret, or having authenticated
//     earlier in the session.
//   - **Authorized like secman.** A section is readable only if the caller's
//     principal holds one of the secman roles the section's policy demands —
//     the same roles the originating secman controller's `@Secured` demands.
//     A user sees on a phone exactly what they would see in the web UI.
//   - **Scoped per device.** On top of the role gate, a device may be granted
//     a subset of its user's sections. A scope can narrow, never widen.
package api

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"time"

	"github.com/schmalle/secman/src/relay/internal/auth"
	"github.com/schmalle/secman/src/relay/internal/devices"
	"github.com/schmalle/secman/src/relay/internal/httpx"
	"github.com/schmalle/secman/src/relay/internal/idp"
	"github.com/schmalle/secman/src/relay/internal/logging"
	"github.com/schmalle/secman/src/relay/internal/model"
	"github.com/schmalle/secman/src/relay/internal/store"
)

// Handler serves the mobile plane.
type Handler struct {
	Store      *store.Store
	Devices    *devices.Registry
	Tokens     *auth.TokenIssuer
	Challenges *auth.ChallengeStore
	Limiter    *httpx.RateLimiter
	Logger     *slog.Logger
	MaxAge     time.Duration

	// Verifiers holds the OIDC verifiers by provider name ("apple", "google").
	// A provider that is not configured simply is not offered.
	Verifiers map[string]*idp.Verifier
	// GitHub is nil when the GitHub login is not configured.
	GitHub *idp.GitHubClient

	// LoginNonces are issued for the OIDC flows; States and Tickets carry the
	// GitHub browser round trip. All three are single-use and key-bound.
	LoginNonces *idp.EphemeralStore
	States      *idp.EphemeralStore
	Tickets     *idp.EphemeralStore

	// EnrollmentCodesEnabled allows the code-based path to be switched off
	// entirely in a deployment that wants federated login only.
	EnrollmentCodesEnabled bool

	Now func() time.Time
}

// Routes registers the mobile plane.
//
// Each unauthenticated route carries its own rate-limit family so that
// hammering one cannot exhaust a legitimate device's budget on another.
func (h *Handler) Routes(mux *http.ServeMux) {
	limited := func(family string, fn http.HandlerFunc) http.Handler {
		return httpx.Chain(fn, httpx.Limit(h.Limiter, family, h.Logger))
	}

	mux.Handle("GET /api/v1/providers", limited("providers", h.handleProviders))

	mux.Handle("POST /api/v1/auth/nonce", limited("login", h.handleNonce))
	mux.Handle("POST /api/v1/auth/oidc", limited("login", h.handleOIDCBind))
	mux.Handle("POST /api/v1/auth/github/start", limited("login", h.handleGitHubStart))
	mux.Handle("GET /api/v1/auth/github/callback", limited("login", h.handleGitHubCallback))
	mux.Handle("POST /api/v1/auth/github/complete", limited("login", h.handleGitHubComplete))
	mux.Handle("POST /api/v1/enroll", limited("enroll", h.handleEnroll))

	mux.Handle("POST /api/v1/auth/challenge", limited("challenge", h.handleChallenge))
	mux.Handle("POST /api/v1/auth/token", limited("token", h.handleToken))

	mux.Handle("GET /api/v1/meta", h.authenticated(h.handleMeta))
	mux.Handle("GET /api/v1/status", h.authenticated(h.handleStatus))
	mux.Handle("GET /api/v1/status/{section}", h.authenticated(h.handleSection))
	mux.Handle("GET /api/v1/session", h.authenticated(h.handleSession))
}

